<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sesiones — Hache Natación</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fa;font-family:Arial,sans-serif;color:#172033}.wrap{max-width:900px;margin:auto;padding:72px 12px 30px}h1{font-size:26px;margin:0 0 5px}.sub{color:#64748b;font-size:13px;margin-bottom:16px}.fecha{width:100%;padding:12px;border:1px solid #cbd5e1;border-radius:12px;background:#fff;font-size:16px;margin-bottom:14px}.sesion{background:#fff;border-radius:16px;padding:14px;margin-bottom:12px;box-shadow:0 3px 12px #0000000d}.top{display:flex;justify-content:space-between;gap:10px;align-items:center}.hora{font-size:19px;font-weight:800}.estado{font-size:11px;font-weight:800;padding:5px 8px;border-radius:999px;background:#e2e8f0}.alumno{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;border-top:1px solid #eef2f7;padding:11px 0}.nombre{font-weight:700}.info{font-size:11px;color:#64748b;margin-top:3px}.checks{display:flex;gap:5px}.checks button,.acciones button{border:0;border-radius:9px;padding:8px 9px;font-weight:800;cursor:pointer}.p{background:#dcfce7;color:#166534}.j{background:#fef3c7;color:#92400e}.f{background:#fee2e2;color:#991b1b}.sel{outline:2px solid #172033}.acciones{display:flex;gap:8px;margin-top:10px}.acciones button{flex:1;background:#172033;color:#fff}.acciones .cancel{background:#fff1f2;color:#9f1239}.vacio{text-align:center;color:#64748b;padding:35px 10px}.alerta{color:#991b1b;font-weight:700}.ok{color:#166534;font-weight:700}@media(min-width:700px){.wrap{padding-top:35px}.alumno{grid-template-columns:1fr 260px}.checks button{padding:9px 14px}}
</style></head><body><main class="wrap"><h1>Sesiones</h1><div class="sub">Asistencia diaria · toca P, J o F por alumno</div><input id="fecha" class="fecha" type="date"><div id="lista"></div></main><script>
const fecha=document.getElementById('fecha'),lista=document.getElementById('lista');fecha.value=new Date().toISOString().slice(0,10);fecha.onchange=cargar;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(body){const r=await fetch('/api/sesiones.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Error');return d}
async function cargar(){lista.innerHTML='<div class="vacio">Cargando…</div>';try{const r=await fetch('/api/sesiones.php?fecha='+fecha.value),d=await r.json();if(!d.ok)throw new Error(d.error);if(!d.sesiones.length){lista.innerHTML='<div class="vacio">No hay sesiones creadas para este día.</div>';return}lista.innerHTML=d.sesiones.map(s=>`<section class="sesion"><div class="top"><div class="hora">${s.hora_inicio?esc(s.hora_inicio.slice(0,5))+'–'+esc(s.hora_fin.slice(0,5)):esc(s.bloque)}</div><span class="estado">${esc(s.estado)}</span></div>${s.alumnos.length?s.alumnos.map(a=>{const acceso=a.intensivo_activo==1||a.mensualidad_estado==='PAGADA';return `<div class="alumno"><div><div class="nombre">${esc(a.nombre)}</div><div class="info ${acceso?'ok':'alerta'}">${a.intensivo_activo==1?'Intensivo':(acceso?'Con derecho a clase':'Sin derecho a clase')}</div></div><div class="checks" data-s="${s.id}" data-a="${a.id}"><button class="p ${a.asistencia_estado==='PRESENTE'?'sel':''}" data-e="PRESENTE">P</button><button class="j ${a.asistencia_estado==='AUSENTE_JUSTIFICADA'?'sel':''}" data-e="AUSENTE_JUSTIFICADA">J</button><button class="f ${a.asistencia_estado==='AUSENTE_NO_JUSTIFICADA'?'sel':''}" data-e="AUSENTE_NO_JUSTIFICADA">F</button></div></div>`}).join(''):'<div class="vacio">Sin alumnos para este horario.</div>'}<div class="acciones">${!s.cerrada?`<button data-close="${s.id}">Cerrar sesión</button><button class="cancel" data-cancel="${s.id}">Cancelar</button>`:''}</div></section>`).join('');}catch(e){lista.innerHTML='<div class="vacio alerta">'+esc(e.message)+'</div>'}}
lista.onclick=async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.e){const g=b.parentElement;await api({accion:'ASISTENCIA',sesion_id:g.dataset.s,alumno_id:g.dataset.a,estado:b.dataset.e});g.querySelectorAll('button').forEach(x=>x.classList.remove('sel'));b.classList.add('sel')}else if(b.dataset.close){if(confirm('¿Cerrar esta sesión?')){await api({accion:'CERRAR',sesion_id:b.dataset.close});cargar()}}else if(b.dataset.cancel){const m=prompt('Motivo de cancelación:');if(m){await api({accion:'CANCELAR',sesion_id:b.dataset.cancel,motivo:m});cargar()}}}catch(err){alert(err.message)}};cargar();
</script></body></html>